/**
 * @method
 * @name scwin.tx_searchSubcomList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_searchSubcomList = async function () {
    const sbmOptions = {
        id: "tx_searchSubcomList",
        method: "post",
        action: "/common/corpList.do?method=searchSubcomList",
        ref: "dma_searchSubcomListReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldods10030.tx_searchSubcomList" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

