/**
 * @event
 * @name scwin.__on_enter_2_ipt_companyName
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.__on_enter_2_ipt_companyName = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin __on_enter_2_ipt_companyName — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        if(($c.util.getKeyCode(ev))==13){ await scwin.searchSubcomList() }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods10030.__on_enter_2_ipt_companyName' }); }
};

/**
 * @method
 * @name scwin.searchSubcomList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.searchSubcomList = async function () {
    /* sdd-asis-lifecycle:begin searchSubcomList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.clearBtnImage();
    $c.util.getComponent('dma_searchSubcomListReq').set('beginIndex', "");
    (document.corpListForm || { elements: [] }).target = "iframe";
    (document.corpListForm || { elements: [] }).action = "/common/corpList.do?method=searchSubcomList";
    await scwin.tx_searchSubcomList();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.searchSubcomListByBeginIndex
 * @author Inswave
