    /* sdd-asis-lifecycle:begin searchSubcomListByBeginIndex — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    (document.corpListForm || { elements: [] }).action = "/common/corpList.do?method=searchSubcomList";
    (document.corpListForm || { elements: [] }).target = "iframe";
    await scwin.tx_searchSubcomListByBeginIndex();
    /* sdd-asis-lifecycle:end */
};


